package alphametics

import (
	"errors"
	"strings"
)

// Solve finds a digit assignment for every letter in the puzzle such that the
// words on the left of "==" sum to the word on the right. Each letter maps to a
// distinct digit, and the leading letter of a multi-digit word may not be zero.
//
// The puzzle is solved with column-wise backtracking: columns are processed
// from the units place upward, and the running carry constrains which digit
// assignments are valid, pruning the search space aggressively.
func Solve(puzzle string) (map[string]int, error) {
	sides := strings.Split(puzzle, "==")
	if len(sides) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}

	var addends []string
	for _, tok := range strings.Fields(sides[0]) {
		if tok != "+" {
			addends = append(addends, tok)
		}
	}
	resultToks := strings.Fields(sides[1])
	if len(resultToks) != 1 {
		return nil, errors.New("invalid puzzle: expected exactly one result word")
	}
	result := resultToks[0]

	words := append(addends, result)
	signs := make([]int, len(words))
	for i := range addends {
		signs[i] = 1
	}
	signs[len(addends)] = -1

	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}

	// term is one letter's contribution to a column, with its sign.
	type term struct {
		let  byte
		sign int
	}

	// cols[pos] holds the letters in the column at `pos` from the right
	// (pos 0 is the units column).
	cols := make([][]term, maxLen)
	leading := make([]bool, 256)
	for i, w := range words {
		if len(w) > 1 {
			leading[w[0]] = true
		}
		for j, c := range w {
			pos := len(w) - 1 - j
			cols[pos] = append(cols[pos], term{byte(c), signs[i]})
		}
	}

	digit := make([]int, 256)
	assigned := make([]bool, 256)
	used := make([]bool, 10)

	var solve func(pos, carry int) bool
	solve = func(pos, carry int) bool {
		if pos == maxLen {
			return carry == 0
		}
		col := cols[pos]

		// Letters in this column that have not been assigned yet.
		newLetters := make([]byte, 0, len(col))
		inNew := make([]bool, 256)
		for _, t := range col {
			if !assigned[t.let] && !inNew[t.let] {
				newLetters = append(newLetters, t.let)
				inNew[t.let] = true
			}
		}

		var rec func(k int) bool
		rec = func(k int) bool {
			// All letters in the column are assigned: verify the column
			// equation and propagate the carry.
			if k == len(newLetters) {
				sum := carry
				for _, t := range col {
					sum += t.sign * digit[t.let]
				}
				if sum < 0 || sum%10 != 0 {
					return false
				}
				return solve(pos+1, sum/10)
			}

			// One letter remains: instead of trying every digit, derive the
			// digit(s) that satisfy the column equation directly.
			if k == len(newLetters)-1 {
				l := newLetters[k]
				coeff, base := 0, carry
				for _, t := range col {
					if t.let == l {
						coeff += t.sign
					} else {
						base += t.sign * digit[t.let]
					}
				}
				for d := 0; d <= 9; d++ {
					if used[d] || (d == 0 && leading[l]) {
						continue
					}
					s := base + coeff*d
					if s < 0 || s%10 != 0 {
						continue
					}
					used[d] = true
					digit[l] = d
					assigned[l] = true
					if solve(pos+1, s/10) {
						return true
					}
					assigned[l] = false
					digit[l] = 0
					used[d] = false
				}
				return false
			}

			l := newLetters[k]
			for d := 0; d <= 9; d++ {
				if used[d] || (d == 0 && leading[l]) {
					continue
				}
				used[d] = true
				digit[l] = d
				assigned[l] = true
				if rec(k + 1) {
					return true
				}
				assigned[l] = false
				digit[l] = 0
				used[d] = false
			}
			return false
		}
		return rec(0)
	}

	if !solve(0, 0) {
		return nil, errors.New("no solution")
	}

	out := make(map[string]int)
	for l := 0; l < 256; l++ {
		if assigned[l] {
			out[string(rune(l))] = digit[l]
		}
	}
	return out, nil
}

